import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor cute_attention(torch::Tensor Q, torch::Tensor K, torch::Tensor V);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>
#include <math.h>

using namespace cute;

__device__ __forceinline__ void cp_async_cg16(void* smem_ptr, const void* gmem_ptr) {
    unsigned smem_addr = static_cast<unsigned>(__cvta_generic_to_shared(smem_ptr));
    asm volatile("cp.async.cg.shared.global [%0], [%1], 16;\n"
                 :: "r"(smem_addr), "l"(gmem_ptr));
}
__device__ __forceinline__ void cp_async_commit_group() {
    asm volatile("cp.async.commit_group;\n");
}
template <int N>
__device__ __forceinline__ void cp_async_wait_group() {
    asm volatile("cp.async.wait_group %0;\n" :: "n"(N));
}
template <int BM_, int BN_, int BK_>
__global__ void attn_kernel(const half* __restrict__ Qg,
                             const half* __restrict__ Kg,
                             const half* __restrict__ Vg,
                             half* __restrict__ Og,
                             int B, int H, int S, int D, float scale)
{
    constexpr int BM = BM_;
    constexpr int BN = BN_;
    constexpr int BK = BK_;
    constexpr int KS_PAD = 8;
    constexpr int KS_STRIDE = BK + KS_PAD;
    int bh = blockIdx.y;
    int b = bh / H;
    int h = bh % H;
    int m_tile = blockIdx.x;
    int m_start = m_tile * BM;
    int tx = threadIdx.x; // 0..BN-1
    int ty = threadIdx.y; // 0..BM-1
    size_t bh_off = (size_t)(b * H + h) * (size_t)S * (size_t)D;
    const half* Qptr = Qg + bh_off;
    const half* Kptr = Kg + bh_off;
    const half* Vptr = Vg + bh_off;
    half* Optr = Og + bh_off;
    Tensor Qt = make_tensor(make_gmem_ptr(Qptr), make_shape(S, D), make_stride(D, 1));
    Tensor Kt = make_tensor(make_gmem_ptr(Kptr), make_shape(S, D), make_stride(D, 1));
    Tensor Vt = make_tensor(make_gmem_ptr(Vptr), make_shape(S, D), make_stride(D, 1));
    Tensor Ot = make_tensor(make_gmem_ptr(Optr), make_shape(S, D), make_stride(D, 1));
    extern __shared__ unsigned char smem_raw[];
    half* Qs_ptr = reinterpret_cast<half*>(smem_raw);
    half* Ks_ptr = Qs_ptr + BM * BK;
    half* Ks_ptr2 = Ks_ptr + BN * KS_STRIDE;
    float* Sc_ptr = reinterpret_cast<float*>(Ks_ptr2 + BN * KS_STRIDE);
    Tensor Qs = make_tensor(make_smem_ptr(Qs_ptr), make_shape(Int<BM>{}, Int<BK>{}), make_stride(Int<BK>{}, Int<1>{}));
    Tensor Ks = make_tensor(make_smem_ptr(Ks_ptr), make_shape(Int<BN>{}, Int<BK>{}), make_stride(Int<KS_STRIDE>{}, Int<1>{}));
    Tensor Sc = make_tensor(make_smem_ptr(Sc_ptr), make_shape(BM, S), make_stride(S, 1));
    int n_tiles = (S + BN - 1) / BN;
    int k_tiles = (D + BK - 1) / BK;
    // Phase 1: compute Q.K^T * scale into Sc
    // Initialize accumulator entries in Sc to zero
    for (int nt = 0; nt < n_tiles; ++nt) {
        int n0 = nt * BN + tx;
        if (n0 < S) {
            Sc(ty, n0) = 0.f;
        }
    }
    __syncthreads();
    // Loop order: kt outer so the Q tile is loaded only once per kt.
    // Global-to-shared loads for Q and K are vectorized via 16-byte (float4)
    // transfers so each thread moves 8 contiguous half elements per
    // instruction, halving the number of kt iterations (and associated
    // __syncthreads() calls) needed to cover the K dimension compared to a
    // 4-wide (float2) vectorized load.
    // The K tiles consumed by the inner nt loop are double buffered: while
    // the dot product for the current K tile is being computed, the K tile
    // needed for the next nt iteration is simultaneously prefetched from
    // global memory into the other buffer. This overlaps global memory
    // latency with compute and reduces the number of __syncthreads() calls
    // from two to one per nt iteration.
    half* Ks_bufs[2] = { Ks_ptr, Ks_ptr2 };
    for (int kt = 0; kt < k_tiles; ++kt) {
        int qm = m_start + ty;
        if (tx < BK / 8) {
            int qk = kt * BK + tx * 8;
            float4 qvec = make_float4(0.f, 0.f, 0.f, 0.f);
            if (qm < S) {
                if (qk + 7 < D) {
                    qvec = *reinterpret_cast<const float4*>(Qptr + (size_t)qm * D + qk);
                } else if (qk < D) {
                    __half* qh = reinterpret_cast<__half*>(&qvec);
                    #pragma unroll
                    for (int e = 0; e < 8; ++e) {
                        int idx = qk + e;
                        if (idx < D) qh[e] = Qptr[(size_t)qm * D + idx];
                    }
                }
            }
            *reinterpret_cast<float4*>(Qs_ptr + ty * BK + tx * 8) = qvec;
        }
        if (tx < BK / 8) {
            int kn0 = ty;
            int kk0 = kt * BK + tx * 8;
            if (kn0 < S && kk0 + 7 < D) {
                cp_async_cg16(Ks_bufs[0] + ty * KS_STRIDE + tx * 8, Kptr + (size_t)kn0 * D + kk0);
            } else {
                float4 kvec0 = make_float4(0.f, 0.f, 0.f, 0.f);
                if (kn0 < S && kk0 < D) {
                    __half* kh0 = reinterpret_cast<__half*>(&kvec0);
                    #pragma unroll
                    for (int e = 0; e < 8; ++e) {
                        int idx = kk0 + e;
                        if (idx < D) kh0[e] = Kptr[(size_t)kn0 * D + idx];
                    }
                }
                *reinterpret_cast<float4*>(Ks_bufs[0] + ty * KS_STRIDE + tx * 8) = kvec0;
            }
            cp_async_commit_group();
            cp_async_wait_group<0>();
        }
        __syncthreads();
        int buf = 0;
        for (int nt = 0; nt < n_tiles; ++nt) {
            int cur = buf;
            int nxt = 1 - buf;
            if (nt + 1 < n_tiles && tx < BK / 8) {
                int kn = (nt + 1) * BN + ty;
                int kk = kt * BK + tx * 8;
                if (kn < S && kk + 7 < D) {
                    cp_async_cg16(Ks_bufs[nxt] + ty * KS_STRIDE + tx * 8, Kptr + (size_t)kn * D + kk);
                } else {
                    float4 kvec = make_float4(0.f, 0.f, 0.f, 0.f);
                    if (kn < S && kk < D) {
                        __half* kh = reinterpret_cast<__half*>(&kvec);
                        #pragma unroll
                        for (int e = 0; e < 8; ++e) {
                            int idx = kk + e;
                            if (idx < D) kh[e] = Kptr[(size_t)kn * D + idx];
                        }
                    }
                    *reinterpret_cast<float4*>(Ks_bufs[nxt] + ty * KS_STRIDE + tx * 8) = kvec;
                }
                cp_async_commit_group();
            }
            float partial = 0.f;
            {
                const __half2* Qs2 = reinterpret_cast<const __half2*>(Qs_ptr + ty * BK);
                const __half2* Ks2 = reinterpret_cast<const __half2*>(Ks_bufs[cur] + tx * KS_STRIDE);
                #pragma unroll
                for (int kk2 = 0; kk2 < BK / 2; ++kk2) {
                    float2 qf = __half22float2(Qs2[kk2]);
                    float2 kf = __half22float2(Ks2[kk2]);
                    partial += qf.x * kf.x + qf.y * kf.y;
                }
            }
            int n = nt * BN + tx;
            if (n < S) {
                Sc(ty, n) += partial;
            }
            if (nt + 1 < n_tiles && tx < BK / 8) {
                cp_async_wait_group<0>();
            }
            __syncthreads();
            buf = nxt;
        }
    }
    // Apply scale after full K-dimension accumulation
    for (int nt = 0; nt < n_tiles; ++nt) {
        int n1 = nt * BN + tx;
        if (n1 < S) {
            Sc(ty, n1) *= scale;
        }
    }
    __syncthreads();
    // Phase 2: softmax over each row, parallelized across the warp (BN == warpSize)
    {
        int m = m_start + ty;
        if (m < S) {
            float local_max = -1e30f;
            for (int n = tx; n < S; n += BN) {
                local_max = fmaxf(local_max, Sc(ty, n));
            }
            #pragma unroll
            for (int offset = 16; offset > 0; offset >>= 1) {
                local_max = fmaxf(local_max, __shfl_xor_sync(0xffffffff, local_max, offset));
            }
            float local_sum = 0.f;
            for (int n = tx; n < S; n += BN) {
                float e = expf(Sc(ty, n) - local_max);
                Sc(ty, n) = e;
                local_sum += e;
            }
            #pragma unroll
            for (int offset = 16; offset > 0; offset >>= 1) {
                local_sum += __shfl_xor_sync(0xffffffff, local_sum, offset);
            }
            float inv = 1.f / local_sum;
            for (int n = tx; n < S; n += BN) {
                Sc(ty, n) *= inv;
            }
        }
    }
    __syncthreads();
    __syncthreads();
    // Phase 3: O = P @ V
    // V loads into shared memory (and outputs) are vectorized via 16-byte
    // (float4) transfers so each thread handles 8 contiguous D columns per
    // iteration, halving the number of dt iterations (and associated
    // __syncthreads() calls) needed to cover the D dimension.
    int d_tiles = (D + BK - 1) / BK;
    half* Vs_bufs[2] = { Ks_ptr, Ks_ptr2 };
    for (int dt = 0; dt < d_tiles; ++dt) {
        float acc0 = 0.f, acc1 = 0.f, acc2 = 0.f, acc3 = 0.f;
        float acc4 = 0.f, acc5 = 0.f, acc6 = 0.f, acc7 = 0.f;
        // Prefetch V tile for nt = 0 into buffer 0
        if (tx < BK / 8) {
            int vn0 = ty;
            int vd0 = dt * BK + tx * 8;
            if (vn0 < S && vd0 + 7 < D) {
                cp_async_cg16(Vs_bufs[0] + ty * KS_STRIDE + tx * 8, Vptr + (size_t)vn0 * D + vd0);
            } else {
                float4 vvec0 = make_float4(0.f, 0.f, 0.f, 0.f);
                if (vn0 < S && vd0 < D) {
                    __half* vh0 = reinterpret_cast<__half*>(&vvec0);
                    #pragma unroll
                    for (int e = 0; e < 8; ++e) {
                        int idx = vd0 + e;
                        if (idx < D) vh0[e] = Vptr[(size_t)vn0 * D + idx];
                    }
                }
                *reinterpret_cast<float4*>(Vs_bufs[0] + ty * KS_STRIDE + tx * 8) = vvec0;
            }
            cp_async_commit_group();
            cp_async_wait_group<0>();
        }
        __syncthreads();
        int vbuf = 0;
        // V tiles are double buffered across the nt loop: while the P@V
        // partial product for the current V tile is being accumulated, the
        // V tile needed for the next nt iteration is prefetched from global
        // memory into the other buffer via cp.async, overlapping global
        // memory latency with compute and reducing __syncthreads() calls
        // from two to one per nt iteration.
        for (int nt = 0; nt < n_tiles; ++nt) {
            int cur = vbuf;
            int nxt = 1 - vbuf;
            if (nt + 1 < n_tiles && tx < BK / 8) {
                int vn = (nt + 1) * BN + ty;
                int vd = dt * BK + tx * 8;
                if (vn < S && vd + 7 < D) {
                    cp_async_cg16(Vs_bufs[nxt] + ty * KS_STRIDE + tx * 8, Vptr + (size_t)vn * D + vd);
                } else {
                    float4 vvec = make_float4(0.f, 0.f, 0.f, 0.f);
                    if (vn < S && vd < D) {
                        __half* vh = reinterpret_cast<__half*>(&vvec);
                        #pragma unroll
                        for (int e = 0; e < 8; ++e) {
                            int idx = vd + e;
                            if (idx < D) vh[e] = Vptr[(size_t)vn * D + idx];
                        }
                    }
                    *reinterpret_cast<float4*>(Vs_bufs[nxt] + ty * KS_STRIDE + tx * 8) = vvec;
                }
                cp_async_commit_group();
            }
            #pragma unroll
            for (int nn = 0; nn < BN; ++nn) {
                int n_global = nt * BN + nn;
                float p = (n_global < S) ? Sc(ty, n_global) : 0.f;
                float4 vv = *reinterpret_cast<const float4*>(Vs_bufs[cur] + nn * KS_STRIDE + tx * 8);
                const __half2* vv2 = reinterpret_cast<const __half2*>(&vv);
                float2 vf0 = __half22float2(vv2[0]);
                float2 vf1 = __half22float2(vv2[1]);
                float2 vf2 = __half22float2(vv2[2]);
                float2 vf3 = __half22float2(vv2[3]);
                acc0 += p * vf0.x;
                acc1 += p * vf0.y;
                acc2 += p * vf1.x;
                acc3 += p * vf1.y;
                acc4 += p * vf2.x;
                acc5 += p * vf2.y;
                acc6 += p * vf3.x;
                acc7 += p * vf3.y;
            }
            if (nt + 1 < n_tiles && tx < BK / 8) {
                cp_async_wait_group<0>();
            }
            __syncthreads();
            vbuf = nxt;
        }
        int m = m_start + ty;
        int d0 = dt * BK + tx * 8;
        int d1 = d0 + 1;
        int d2 = d0 + 2;
        int d3 = d0 + 3;
        int d4 = d0 + 4;
        int d5 = d0 + 5;
        int d6 = d0 + 6;
        int d7 = d0 + 7;
        if (m < S && tx < BK / 8) {
            if (d0 < D) {
                Ot(m, d0) = __float2half(acc0);
            }
            if (d1 < D) {
                Ot(m, d1) = __float2half(acc1);
            }
            if (d2 < D) {
                Ot(m, d2) = __float2half(acc2);
            }
            if (d3 < D) {
                Ot(m, d3) = __float2half(acc3);
            }
            if (d4 < D) {
                Ot(m, d4) = __float2half(acc4);
            }
            if (d5 < D) {
                Ot(m, d5) = __float2half(acc5);
            }
            if (d6 < D) {
                Ot(m, d6) = __float2half(acc6);
            }
            if (d7 < D) {
                Ot(m, d7) = __float2half(acc7);
            }
        }
    }
}
torch::Tensor cute_attention(torch::Tensor Q, torch::Tensor K, torch::Tensor V) {
    TORCH_CHECK(Q.is_cuda() && K.is_cuda() && V.is_cuda(), "Q,K,V must be CUDA tensors");
    TORCH_CHECK(Q.scalar_type() == at::kHalf && K.scalar_type() == at::kHalf && V.scalar_type() == at::kHalf,
                "Expect float16 tensors");
    TORCH_CHECK(Q.dim() == 4, "Expect 4D tensors (B,H,S,D)");
    auto Qc = Q.contiguous();
    auto Kc = K.contiguous();
    auto Vc = V.contiguous();
    int B = (int)Qc.size(0);
    int H = (int)Qc.size(1);
    int S = (int)Qc.size(2);
    int D = (int)Qc.size(3);
    auto O = torch::empty_like(Qc);
    constexpr int BM = 32;
    constexpr int BN = 32;
    constexpr int BK = 64;
    constexpr int KS_PAD = 8;
    float scale = 1.0f / sqrtf((float)D);
    dim3 block(BN, BM);
    dim3 grid((S + BM - 1) / BM, B * H);
    size_t smem_bytes = (size_t)BM * BK * sizeof(half) +
                         (size_t)BN * (BK + KS_PAD) * sizeof(half) * 2 +
                         (size_t)BM * S * sizeof(float);
    auto kernel_ptr = attn_kernel<BM, BN, BK>;
    if (smem_bytes > 48 * 1024) {
        cudaError_t attr_err = cudaFuncSetAttribute(kernel_ptr, cudaFuncAttributeMaxDynamicSharedMemorySize, (int)smem_bytes);
        TORCH_CHECK(attr_err == cudaSuccess,
                    "Failed to opt-in to ", smem_bytes, " bytes of dynamic shared memory: ",
                    cudaGetErrorString(attr_err));
    }
    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
    kernel_ptr<<<grid, block, smem_bytes, stream>>>(
        reinterpret_cast<const half*>(Qc.data_ptr<at::Half>()),
        reinterpret_cast<const half*>(Kc.data_ptr<at::Half>()),
        reinterpret_cast<const half*>(Vc.data_ptr<at::Half>()),
        reinterpret_cast<half*>(O.data_ptr<at::Half>()),
        B, H, S, D, scale);
    TORCH_CHECK(cudaGetLastError() == cudaSuccess, "CUTE attention kernel launch failed");
    return O;
}
"""

cute_ext = load_inline(
    name="cute_attention_ext",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["cute_attention"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/workspace/cutegen_test/cutegen/cutlass/include"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()
        self._ext = cute_ext

    def forward(self, Q: torch.Tensor, K: torch.Tensor, V: torch.Tensor) -> torch.Tensor:
        return self._ext.cute_attention(Q, K, V)

